package com.orderflow.notification.config;import io.micrometer.core.instrument.MeterRegistry;import java.util.Map;import org.apache.kafka.clients.admin.*;import org.apache.kafka.common.TopicPartition;import org.springframework.boot.health.contributor.*;import org.springframework.context.annotation.*;import org.springframework.kafka.config.TopicBuilder;import org.springframework.kafka.core.*;import org.springframework.kafka.listener.*;import org.springframework.util.backoff.FixedBackOff;@Configuration public class KafkaConfiguration{@Bean NewTopic notificationTopic(KafkaTopicProperties p){return TopicBuilder.name(p.notificationEvents()).partitions(3).replicas(1).build();}@Bean NewTopic notificationDlt(KafkaTopicProperties p){return TopicBuilder.name(p.notificationEventsDlt()).partitions(3).replicas(1).build();}@Bean DefaultErrorHandler notificationKafkaErrorHandler(KafkaTemplate<String,String>t,KafkaTopicProperties p,MeterRegistry m){DeadLetterPublishingRecoverer r=new DeadLetterPublishingRecoverer(t,(record,e)->{m.counter("orderflow_kafka_dlt_publications_total","service","notification-service").increment();return new TopicPartition(p.notificationEventsDlt(),record.partition());});DefaultErrorHandler h=new DefaultErrorHandler(r,new FixedBackOff(500,2));h.setCommitRecovered(true);return h;}@Bean HealthIndicator kafkaHealthIndicator(KafkaAdmin a){Map<String,Object>c=a.getConfigurationProperties();return()->{AdminClient x=AdminClient.create(c);try{x.listTopics().names().get(3, java.util.concurrent.TimeUnit.SECONDS);return Health.up().build();}catch(InterruptedException e){Thread.currentThread().interrupt();return Health.down().build();}catch(Exception e){return Health.down().build();}finally{x.close(java.time.Duration.ZERO);}};}}
